// src/runtime/NKZContext.ts
import { createContext, useContext } from "react";
var NKZContext = createContext(null);
function useNKZRuntime() {
  const runtime = useContext(NKZContext);
  if (!runtime) {
    throw new Error(
      "[@nekazari/module-kit] No NKZProvider in the React tree. In production this is provided by the host; in `nkz dev` use MockProvider from @nekazari/module-kit/mock."
    );
  }
  return runtime;
}

export {
  NKZContext,
  useNKZRuntime
};
